 class EnvVarCheck
 {
     void CheckFlag()
     {
         // On Linux, set via: export MY_FLAG=""
         // .NET 9 breaking change: GetEnvironmentVariable now returns null
         // for empty env vars on Unix (previously returned "").
         // Use !Exists to detect "not set" vs "explicitly empty".
         if (!IsEnvironmentVariableSet("MY_FLAG"))
         {
             Console.WriteLine("MY_FLAG not set, using default");
         }
     }

     static bool IsEnvironmentVariableSet(string name)
     {
         var envVars = Environment.GetEnvironmentVariables();
         return envVars.Contains(name);
     }
     }
 }

